import{z as n,x as p,o as t,c as B,q as E,j as s,D as a,d as o,s as l,S as A}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Checkpoint 与 resume","description":"","frontmatter":{"title":"Checkpoint 与 resume","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pretrain-ckpt.md","filePath":"llm/pretrain-ckpt.md","lastUpdated":1791063341000}'),i={name:"llm/pretrain-ckpt.md"};function c(d,e,m,h,u,D){const r=p("Mermaid");return t(),B("div",null,[e[2]||(e[2]=E('<h1 id="checkpoint-与-resume" tabindex="-1">Checkpoint 与 resume <a class="header-anchor" href="#checkpoint-与-resume" aria-label="Permalink to &quot;Checkpoint 与 resume&quot;">​</a></h1><div class="epigraph"><p>能 resume 的不是「存了权重」，而是权重、优化器、进度与随机源在下一次 step 能接上同一条轨迹；缺任何一项，都只是从一份快照重新开训。</p><footer>—— 综合 PyTorch 分布式检查点与 Megatron / DeepSpeed 预训练实践</footer></div><p><a href="/llm/sequence-packing">上一课</a>把短文档装进固定窗口，用分隔 token、按篇重置位置与篇间注意力屏蔽钉住边界。训练仍会掉电、抢占、坏盘，墙钟以周计。缺口是检查点与 resume：要覆盖参数、优化器、日程、scaler、RNG 与数据进度，并分清精确轨迹与够用的续训。本课写保存清单与原子发布，不重讲 <code>cu_seqlens</code> 与装箱算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一步训练的状态包括：参数 \\(\\theta\\)、优化器状态（Adam 的 \\(m,v\\)、步数）、学习率日程的进度、梯度缩放器（若用损失缩放）、RNG（CPU、CUDA、dataloader worker）、以及数据迭代器位置。只存 \\(\\theta\\)，resume 后用新的空优化器，等效于在该点做一次学习率与动量重置，损失曲线会跳，不能当同一实验。只存 \\(\\theta\\) 与优化器、不存数据位置，会重复或跳过文档，packing 后的样本顺序一旦错位，所谓续训是另一条数据轨迹。</p><p><span class="marginnote">数字实例：7B 模型的权重按 FP16 存约 14 GB；Adam 还要再存 \\(m\\)、\\(v\\) 两份同尺寸状态（常配 FP32，合计轻松超过权重的 2-3 倍）。这就是有人只存权重的原因——省下几十 GB——但代价是 resume 从「接上轨迹」退化成「换个起点重训」。</span></p><p>分布式下问题更硬。ZeRO-3 参数分片、流水线各段、张量并行切片，检查点必须记录并行拓扑。用 64 卡保存的分片，不能假装在 32 卡上直接 <code>load_state_dict</code>。故障模型也不同：单步失败要回滚到上一个完整检查点；存储写到一半的文件是损坏检查点，resume 必须能选「最后一个完整的」，而不是目录里时间戳最新的。</p>',7)),(t(),s(A,null,{default:a(()=>[l(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20CKPT%5B%22%E4%B8%80%E6%AC%A1%E4%BF%9D%E5%AD%98%E8%AF%A5%E5%90%AB%E4%BB%80%E4%B9%88%3F%22%5D%20--%3E%20THETA%5B%22%E5%8F%AA%E5%AD%98%E5%8F%82%E6%95%B0%20theta%22%5D%0A%20%20THETA%20--%3E%20NOOPT%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%20m%20%E4%B8%8E%20v%20%E8%A2%AB%E6%B8%85%E9%9B%B6%22%5D%0A%20%20NOOPT%20--%3E%20JUMP%5B%22%E5%8A%A8%E9%87%8F%E4%B8%8E%E8%87%AA%E9%80%82%E5%BA%94%E5%B0%BA%E5%BA%A6%E9%87%8D%E7%BD%AE%2C%20%E6%8D%9F%E5%A4%B1%E6%9B%B2%E7%BA%BF%E8%B7%B3%E5%8F%98%22%5D%0A%20%20THETA%20--%3E%20NODATA%5B%22%E4%B8%8D%E5%AD%98%E6%95%B0%E6%8D%AE%E8%BF%9B%E5%BA%A6%22%5D%0A%20%20NODATA%20--%3E%20DUP%5B%22%E9%87%8D%E5%A4%8D%E6%88%96%E8%B7%B3%E8%BF%87%E6%96%87%E6%A1%A3%2C%20%E6%8D%A2%E4%B8%80%E6%9D%A1%E6%95%B0%E6%8D%AE%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20FULL%5B%22%E5%AE%8C%E6%95%B4%E6%B8%85%E5%8D%95%3A%20%E5%8F%82%E6%95%B0%2B%E4%BC%98%E5%8C%96%E5%99%A8%2B%E6%97%A5%E7%A8%8B%2BRNG%2B%E6%95%B0%E6%8D%AE%E8%BF%9B%E5%BA%A6%22%5D%20--%3E%20SAME%5B%22resume%20%E6%8E%A5%E4%B8%8A%E5%90%8C%E4%B8%80%E6%9D%A1%E8%BD%A8%E8%BF%B9%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E('<h3 id="完整轨迹-vs-够用的续训" tabindex="-1">完整轨迹 vs 够用的续训 <a class="header-anchor" href="#完整轨迹-vs-够用的续训" aria-label="Permalink to &quot;完整轨迹 vs 够用的续训&quot;">​</a></h3><p>精确复现要求：同一软件版本、同一并行度、同一 RNG、同一数据顺序，从检查点接着 step。实践里常放宽：换卡数、换框架版本、只加载权重做退火。放宽应改实验名，不要与原 run 画在同一条损失曲线上假装连续。够用的续训（例如丢了 dataloader 状态但优化器还在）对最终质量可能够用，对论文里的 step-wise 对比不够用。先定义这次作业要哪一种，再决定保存清单。</p><p><span class="marginnote">「异步检查点不阻塞训练」只说明拷贝与计算重叠。若后台线程还在写，前台已经改了被拷内存，存下来的是撕裂状态。必须先冻结一份快照（拷到预留缓冲或用版本计数），再异步刷盘。速度优化不能破坏原子性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>保存清单最低应是：模型、优化器、日程、global step、RNG、数据进度（样本索引或 shuffle epoch + 偏移）、以及并行配置与代码/配置哈希。格式上，PyTorch Distributed Checkpoint（DCP）按张量名与分片元数据写，便于改并行度加载；Megatron 一类则按 TP/PP rank 落文件。两者都要写 <code>latest</code> 指针与 <code>complete</code> 标记：先写临时目录，fsync，再原子改名。保留最近 \\(N\\) 个与每隔 \\(K\\) 步的永久点，避免磁盘被逐步文件填满，也避免坏掉最后一个时无路可退。</p><p><span class="marginnote">常见误区：「写进目录就等于存好了」。大模型检查点动辄上百 GB，落盘加网络上传常以分钟计，这段窗口里掉电就是半成品。没有 complete 标记与校验和，时间戳最新的目录很可能恰恰是残缺的——resume 读到它，比回滚丢几天进度更糟。</span></p><p>数据进度在 web 语料上要用确定性 shuffle：种子加 epoch，记录已经消费的全局索引。packing 后应以 packed 样本 ID 为进度，而不是原始文档 ID，否则 resume 会把半个桶再装一次。评估循环不要破坏训练 RNG：eval 用独立生成器，或保存/恢复训练生成器。混合精度的 scaler 状态必须存，否则 resume 后第一步可能溢出或过度缩放。</p><h3 id="异步、频率与转换" tabindex="-1">异步、频率与转换 <a class="header-anchor" href="#异步、频率与转换" aria-label="Permalink to &quot;异步、频率与转换&quot;">​</a></h3><p>检查点频率是故障平均时间（MTBF）与写放大之间的权衡。步间隔太短，HBM 到对象存储的带宽吃掉有效训练；太长，故障回滚丢失几天。异步写把「序列化 + 上传」移出关键路径，但需要双缓冲内存。对象存储上应用分片并行上传，并校验 ETag / 校验和。需要对外发布时，另做一份「仅权重」转换（HF、Megatron 导出），不要让研究 resume 依赖发布格式——发布格式通常丢掉优化器。从 ZeRO 分片合并成整模型，是另一次作业，应在空闲时做，失败不得影响训练目录里的权威检查点。</p>',9)),(t(),s(A,null,{default:a(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22Step%20t%20%E5%AE%8C%E6%88%90%22%5D%20--%3E%20SNAP%5B%22%E5%86%BB%E7%BB%93%E5%8F%82%E6%95%B0%E4%B8%8E%E4%BC%98%E5%8C%96%E5%99%A8%E5%BF%AB%E7%85%A7%22%5D%0A%20%20SNAP%20--%3E%20META%5B%22%E5%86%99%E5%85%A5%20step%20%2F%20RNG%20%2F%20%E6%95%B0%E6%8D%AE%E8%BF%9B%E5%BA%A6%22%5D%0A%20%20SNAP%20--%3E%20ASY%5B%22%E5%BC%82%E6%AD%A5%E5%88%B7%E5%AF%B9%E8%B1%A1%E5%AD%98%E5%82%A8%22%5D%0A%20%20META%20--%3E%20FLAG%5B%22complete%20%E6%A0%87%E8%AE%B0%20%2B%20latest%20%E6%8C%87%E9%92%88%22%5D%0A%20%20ASY%20--%3E%20FLAG%0A%20%20FAIL%5B%22%E6%95%85%E9%9A%9C%22%5D%20--%3E%20L%5B%22%E8%AF%BB%E5%8F%96%E6%9C%80%E5%90%8E%E4%B8%80%E4%B8%AA%20complete%22%5D%0A%20%20L%20--%3E%20R%5B%22%E6%81%A2%E5%A4%8D%E5%B9%B6%E8%A1%8C%E6%8B%93%E6%89%91%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%81%8F%E7%A7%BB%22%5D%0A%20%20R%20--%3E%20S2%5B%22Step%20t%2B1%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=E('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Resume 的数值机制是：优化器的 \\(m,v\\) 与当前 \\(\\theta\\)、当前 lr 必须来自同一 step。Adam 的自适应尺度依赖历史梯度平方；清零 \\(v\\) 会让更新突然变大。数据机制是经验分布的遍历：有放回或无放回、是否按 token 加权，都由迭代器状态编码。RNG 机制覆盖 dropout、数据增强与任何随机层；CUDA 图与异步核使「只存 Python RNG」不够，还要 <code>torch.cuda.get_rng_state_all()</code> 一类。并行机制是切片对齐：加载时按当时的 TP/PP/DP 重切或用 DCP 的 reshard。</p><p>完整性机制靠两阶段提交：数据可见之前不更新 <code>latest</code>。读侧只跟随 <code>latest</code> 指向的 complete 目录。这与数据库 WAL 思想相同，只是粒度是「整个训练状态」。</p><p><span class="marginnote">直觉类比：原子改名像搬家换门牌——先在新地址把家具全部码好（写临时目录并 fsync），一切就绪才把门牌挂过去（原子 rename）。中途出事，老门牌还挂在旧房子上，下次接着搬即可；绝不出现「门牌换了、家具还在路上」的状态。</span></p><p><span class="marginnote">激活重计算检查点与训练检查点都叫 checkpoint，日志里应分开说。前者是 autograd 图上的保留张量；后者是作业级快照。混淆二者会导致有人「开了 checkpoint」却在节点被杀后从 step 0 重来。</span></p><h3 id="与-zero、流水线的耦合" tabindex="-1">与 ZeRO、流水线的耦合 <a class="header-anchor" href="#与-zero、流水线的耦合" aria-label="Permalink to &quot;与 ZeRO、流水线的耦合&quot;">​</a></h3><p>ZeRO-1 只分片优化器，保存时要 all-gather 或按 rank 各写一份再在 resume 时校验步数一致。流水线并行下，各 stage 的模块不同，必须所有 stage 都写完才算 complete，否则会出现「后段新、前段旧」的拼接模型。张量并行的 embedding 与输出头切片同样。故障若只杀掉部分 rank，不要试图从活着的 rank 内存拼一份检查点，除非明确实现了一致性协议；默认回滚到上一个 complete。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>精确复现与弹性扩缩冲突。允许改卡数 resume，就要接受 DCP reshard 的代价与可能的数值微差（归约顺序）。允许换 CUDA / 框架版本，RNG 与内核实现都会变。对象存储最终一致时，「写完立刻在另一区域读」可能读到旧 <code>latest</code>，应用版本号或强一致列表。安全上，检查点含完整模型与数据进度，访问控制应与训练数据同级；不要把带优化器的目录公开成 HF 仓库。</p><p>测试 resume 应纳入 CI：训几步、存、再训几步，与不中断的损失对比（允许浮点噪声）。从未测过的检查点格式，等于没有容错。长跑中途改 packing、改过滤配方，即使权重接上，数据轨迹也断了，应升实验版本。</p><p><span class="marginnote">「最后一个检查点的损失更低」不能证明 resume 正确。正确性看 resume 后第一步的 loss 是否与保存前一步连续，以及数据指纹是否接上。损失碰巧下降，可能只是重复数据或 lr 被重置到更甜的点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>训练检查点要覆盖参数、优化器、日程、scaler、RNG 与数据进度，外加并行拓扑。</li><li>Resume 分精确轨迹与够用的续训；混画损失曲线是实验错误。</li><li>用临时目录 + complete 标记做原子发布；<code>latest</code> 只指向完整快照。</li><li>异步保存必须先冻结快照，防止撕裂；频率按 MTBF 与写放大权衡。</li><li>发布用的仅权重格式不是 resume 权威源。</li><li>ZeRO / 流水线必须全 rank 一致完成才算一次检查点。</li><li>出处：PyTorch Distributed Checkpoint 文档；Shoeybi et al., Megatron-LM；Rajbhandari et al., ZeRO / DeepSpeed。</li></ul>',13))])}const P=n(i,[["render",c]]);export{T as __pageData,P as default};
